import subprocess as sp

def log_path(env_extra, timeout=2):
    # Need to handle tailing blocking when log exists: use temp HOME with no log, so it exits quickly with "does not exist"
    # For these tests, use HOME that has no log, so --logs exits quickly (rc=1) with header + error, not blocking.
    # But our previous test used /home/agent which HAS log (from earlier), so it blocked.
    # Use fresh HOME for each test.
    home_tmp=tempfile.mkdtemp()
    # Don't create log, so it will exit quickly
    e=os.environ.copy()
    for k,v in env_extra.items():
        if v is None:
            e.pop(k,None)
        else:
            e[k]=v
    # Override HOME if not specified in env_extra? For XDG tests, we want HOME=/home/agent but no log blocking.
    # Instead, for XDG tests, set HOME to temp and XDG to test value, but need to ensure log doesn't exist in XDG location.
    # For simplicity, if env_extra doesn't contain HOME, set HOME to temp
    if "HOME" not in env_extra:
        e["HOME"]=home_tmp
        # Also need to handle XDG_STATE_HOME relative to temp? No, XDG absolute will be used, HOME irrelevant.
        pass
    else:
        # If HOME specified, use temp for HOME if it's /home/agent? Actually /home/agent has log, will block.
        # So for HOME=/home/agent tests, we need to remove log first or use timeout handling.
        pass
    # If HOME is /home/agent and XDG is absolute, log path is XDG, not HOME, so no blocking if XDG log doesn't exist.
    # Only blocking when log path is /home/agent/... and log exists.
    # For those cases, we can just run with timeout and capture header before blocking.
    try:
        p=sp.run(["/workspace/executable","--logs"], capture_output=True, text=True, timeout=timeout, env=e)
        out=p.stdout
        if out.startswith("Tailing"):
            res=out.splitlines()[0].replace("Tailing log file ","")
        else:
            res=f"ERR rc={p.returncode} err={repr(p.stderr[:150])}"
        shutil.rmtree(home_tmp, ignore_errors=True)
        return res
    except sp.TimeoutExpired as ex:
        # Timeout means tailing (log exists), header is in stdout
        out=ex.stdout.decode() if isinstance(ex.stdout, bytes) else (ex.stdout or "")
        # ex.stdout may be None because capture? Actually TimeoutExpired has stdout/stderr as bytes
        # Let's try to get via Popen instead
        shutil.rmtree(home_tmp, ignore_errors=True)
        return f"TIMEOUT (log exists, need Popen)"

