	// Run git --version, capture stdout, TrimPrefix "git version ", TrimSpace
	// Ignore errors, return "" on failure
	// Need to implement without importing os/exec? Use os/exec.
	return getGitVersionImpl()
}

func printConfig() {
	// Print default config (embedded)
	fmt.Print(defaultConfig)
}

func printConfigDir(strVals map[string]string) {
	dir := resolveConfigDir(strVals)
	fmt.Println(dir)
}

func resolveConfigDir(strVals map[string]string) string {
	// Precedence: flag > CONFIG_DIR env > XDG_CONFIG_HOME (if abs) > HOME
	if v, ok := strVals["use-config-dir"]; ok && v != "" {
		return cleanPath(v)
	}
	if v := os.Getenv("CONFIG_DIR"); v != "" {
		return cleanPath(v)
	}
	if v := os.Getenv("XDG_CONFIG_HOME"); v != "" && filepath.IsAbs(v) {
		return cleanPath(v + "/lazygit")
		// Actually need filepath.Join? But Join cleans. For XDG="/", Join("/","lazygit")="/lazygit". Good. For "/tmp/with//double", Join cleans to single. Good.
		// Use filepath.Join to match? But Join("",...) issue doesn't apply since XDG is abs (non-empty).
	}
	home := os.Getenv("HOME")
	// For HOME, use Clean(HOME + "/.config/lazygit") to handle empty HOME -> "/.config/lazygit"
	return cleanPath(home + "/.config/lazygit")
}

func cleanPath(p string) string {
	// filepath.Clean, but preserve empty? Clean("") returns ".", but we never call with "" (checked non-empty before).
	// For flag/CONFIG_DIR, if p is "relative/path", Clean gives same. Good.
	// For XDG/HOME paths, already constructed.
	return filepath.Clean(p)
}

func doLogs(strVals map[string]string) int {
	// Stub for now
	fmt.Fprintln(os.Stderr, "logs not implemented")
	return 1
}

func logFatal(msg string) {
	// Go log with date/time: "2006/01/02 15:04:05 msg"
	// Use time.Now().Format("2006/01/02 15:04:05") + " " + msg + "\n" to stderr
	// Need to import time, log? Use log package with default flags? log.New(os.Stderr, "", log.LstdFlags) gives same format (with local time).
