func isValidKeybinding(s string) bool {
	if s == "" {
		return true
	}
	// Single rune?
	if len([]rune(s)) == 1 {
		return true
	}
	// Must be <...>
	if len(s) > 2 && s[0] == '<' && s[len(s)-1] == '>' {
		inner := s[1 : len(s)-1]
		if inner == "disabled" {
			return true
		}
		// Case-insensitive check for others (lowercase inner)
		low := strings.ToLower(inner)
		// f1-f12
		if len(low) >= 2 && low[0] == 'f' {
			// f1-f12: check if f + number 1-12
			numStr := low[1:]
			if numStr == "1" || numStr == "2" || numStr == "3" || numStr == "4" || numStr == "5" || numStr == "6" || numStr == "7" || numStr == "8" || numStr == "9" || numStr == "10" || numStr == "11" || numStr == "12" {
				return true
			}
		}
		switch low {
		case "insert", "delete", "home", "end", "pgup", "pgdown",
			"up", "down", "left", "right",
			"s-up", "s-down",
			"tab", "backtab", "enter", "a-enter", "esc", "backspace", "space",
			"c-space", "c-/":
			return true
		}
		// c-a to c-z except h,i,m
		if len(low) == 3 && low[0] == 'c' && low[1] == '-' {
			c := low[2]
			if c >= 'a' && c <= 'z' && c != 'h' && c != 'i' && c != 'm' {
				return true
			}
			if c == '4' || c == '5' || c == '6' || c == '8' {
				return true
			}
		}
		return false
	}
	return false
}
