var versionRegex = regexp.MustCompile(`(\d+)\.(\d+)(?:\.(\d+))?`)

func parseGitVersion(output string) (major, minor, patch int, ok bool) {
	// Find first match of version numbers in output (stdout only, after Trim? Actually for version check, use regex on stdout as is (not TrimPrefix? Since leading spaces still pass, regex finds numbers anywhere).
	// For output like "git version 2.32.0", find "2.32.0". For "  git version 2.32.0", find same. For "v2.32.0", find "2.32.0". Good.
	m := versionRegex.FindStringSubmatch(output)
	if m == nil {
		return 0, 0, 0, false
	}
	major, _ = strconv.Atoi(m[1])
	minor, _ = strconv.Atoi(m[2])
	if m[3] != "" {
		patch, _ = strconv.Atoi(m[3])
	} else {
		patch = 0
	}
	return major, minor, patch, true
}

func isGitVersionSufficient(output string) bool {
	maj, min, pat, ok := parseGitVersion(output)
	if !ok {
		return false
	}
	// Compare >= 2.32.0
	if maj > 2 {
		return true
	}
	if maj < 2 {
		return false
	}
	// maj == 2
	if min > 32 {
		return true
	}
	if min < 32 {
		return false
	}
	// min == 32
	return pat >= 0 // 2.32.x always passes (since x >=0). Actually 2.32.0 passes, 2.32 (patch 0) passes. Good.
	// Note: what about 2.32 with no patch? pat=0, passes. Good.
}

func runGitCommand(args []string, cwd string, debug bool, logLevel string, logFile *os.File) (stdout, stderr string, exitCode int, duration time.Duration) {
	// args like ["--version"] or ["-C", "/tmp/...", "rev-parse", ...]
