func doLogs(strVals map[string]string) int {
	// Resolve log path and ensure dir (for non-overridden, create state dir; for overridden, don't create)
	var logPath, logDir string
	var overridden bool
	if v, ok := strVals["use-config-dir"]; ok && v != "" {
		logDir = filepath.Clean(v)
		overridden = true
	} else if v := os.Getenv("CONFIG_DIR"); v != "" {
		logDir = filepath.Clean(v)
		overridden = true
	} else {
		// Use state dir
		if v := os.Getenv("XDG_STATE_HOME"); v != "" && filepath.IsAbs(v) {
			logDir = filepath.Clean(filepath.Join(v, "lazygit"))
		} else {
			home := os.Getenv("HOME")
			logDir = filepath.Clean(home + "/.local/state/lazygit")
		}
		overridden = false
