package main

import (
	"os/exec"
)

func runStty(args ...string) error {
	// stty -F /dev/tty <args>
	cmd := exec.Command("stty", append([]string{"-F", "/dev/tty"}, args...)...)
	return cmd.Run()
}

func runGitToplevel() (string, error) {
	cmd := exec.Command("git", "rev-parse", "--show-toplevel")
	out, err := cmd.Output()
	if err != nil {
		return "", err
	}
	// TrimSpace
	s := string(out)
	// Remove trailing newline/spaces
	for len(s) > 0 && (s[len(s)-1] == '\n' || s[len(s)-1] == '\r' || s[len(s)-1] == ' ' || s[len(s)-1] == '\t') {
		s = s[:len(s)-1]
	}
	// Remove leading spaces? Unlikely. Just TrimSpace via manual?
	for len(s) > 0 && (s[0] == ' ' || s[0] == '\t' || s[0] == '\n' || s[0] == '\r') {
		s = s[1:]
	}
	return s, nil
}
